  it("leaves every other state exactly as it was", () => {
    expect(stateTone("submitted")).toBe("ok");
    expect(stateTone("approved")).toBe("accent");
    expect(stateTone("queued_review")).toBe("warn");
    expect(stateTone("no_fit")).toBe("danger");
    expect(stateTone("discovered")).toBe("off");
  });
});

describe("presentedState", () => {
  it("passes a non-error state straight through", () => {
    expect(presentedState("submitted", null)).toEqual({
      key: "submitted",
      tone: "ok",
    });
  });

  it("shows an errored row as pending, whatever the report says", () => {
    for (const reason of [
      "Cloudflare challenge on the apply page",
      "the submit button did not respond",
      "something nobody wrote a pattern for",
      null,
    ]) {
      expect(presentedState("error", reason).key).toBe("pending");
    }
  });

  it("keeps a warm tone only where the person can actually move it", () => {
    expect(
      presentedState("error", "We need your login for this platform.").tone,
    ).toBe("warn");
    expect(
      presentedState("error", "We need your answers before this form can go.")
        .tone,
    ).toBe("warn");
  });

  it("stays neutral for the walls and the bugs that are ours to fix", () => {
    expect(presentedState("error", "hCaptcha blocked the browser").tone).toBe(
      "off",
    );
    expect(
      presentedState("error", "no page progress after 12 action turns").tone,
    ).toBe("off");
    expect(
      presentedState(
        "error",
        "this posting is no longer accepting applications",
      ).tone,
    ).toBe("off");
  });
});


